WITH f AS (SELECT * FROM fishing WHERE item_id IS NOT NULL AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), rl AS (SELECT max(release) AS release FROM captures WHERE capture_id IN (SELECT capture_id FROM f)), it AS (SELECT id, name FROM item_names WHERE release = (SELECT release FROM rl)), zn AS (SELECT id, name FROM zone_names WHERE release = (SELECT release FROM rl)), wn AS (SELECT id, name FROM weather_names), p AS (SELECT item_id, groupArray((rod_id, count, n, round(s_avg), s_lo, s_hi, d_lo, d_hi, m_lo, m_hi, a_lo, a_hi, r_lo, r_hi, t_lo, t_hi, g_lo, g_hi, i_lo, i_hi)) AS v FROM (SELECT item_id, rod_id, count, count() AS n, avg(stamina) AS s_avg, min(stamina) AS s_lo, max(stamina) AS s_hi, min(arrow_delay) AS d_lo, max(arrow_delay) AS d_hi, min(move_frequency) AS m_lo, max(move_frequency) AS m_hi, min(arrow_damage) AS a_lo, max(arrow_damage) AS a_hi, min(arrow_regen) AS r_lo, max(arrow_regen) AS r_hi, min(time) AS t_lo, max(time) AS t_hi, min(regen) AS g_lo, max(regen) AS g_hi, min(intuition) AS i_lo, max(intuition) AS i_hi FROM f GROUP BY item_id, rod_id, count ORDER BY n DESC, rod_id, count) GROUP BY item_id), z AS (SELECT item_id, groupArray((key, name, n)) AS v FROM (SELECT f.item_id AS item_id, f.zone_id AS key, any(zn.name) AS name, count() AS n FROM f LEFT JOIN zn ON zn.id = f.zone_id GROUP BY item_id, key ORDER BY n DESC, key) GROUP BY item_id), rd AS (SELECT item_id, groupArray((key, name, n)) AS v FROM (SELECT f.item_id AS item_id, f.rod_id AS key, any(it.name) AS name, count() AS n FROM f LEFT JOIN it ON it.id = f.rod_id GROUP BY item_id, key ORDER BY n DESC, key) GROUP BY item_id), bt AS (SELECT item_id, groupArray((key, name, n)) AS v FROM (SELECT f.item_id AS item_id, f.bait_id AS key, any(it.name) AS name, count() AS n FROM f LEFT JOIN it ON it.id = f.bait_id GROUP BY item_id, key ORDER BY n DESC, key) GROUP BY item_id), w AS (SELECT item_id, groupArray((key, name, n)) AS v FROM (SELECT f.item_id AS item_id, f.weather_id AS key, any(wn.name) AS name, count() AS n FROM f LEFT JOIN wn ON wn.id = f.weather_id GROUP BY item_id, key ORDER BY n DESC, key) GROUP BY item_id) SELECT f.item_id AS item, any(it.name) AS name, count() AS n, uniq(f.capture_id) AS captures, groupUniqArray(f.angler_sense) AS sense, round(2 * avgIf(f.stamina, f.count = 1) / 100 - 36) AS skill, sumMap([f.vana_hour], [toUInt64(1)]) AS hours, sumMap([f.vana_weekday], [toUInt64(1)]) AS days, sumMap([intDiv(f.moon_phase + 5, 10) * 10], [toUInt64(1)]) AS moons, max(f.ts_ms) AS last, argMax(f.capture_id, f.ts_ms) AS last_capture, any(p.v) AS params, any(z.v) AS zones, any(rd.v) AS rods, any(bt.v) AS baits, any(w.v) AS weathers, (SELECT release FROM rl) AS release FROM f LEFT JOIN it ON it.id = f.item_id LEFT JOIN p ON p.item_id = f.item_id LEFT JOIN z ON z.item_id = f.item_id LEFT JOIN rd ON rd.item_id = f.item_id LEFT JOIN bt ON bt.item_id = f.item_id LEFT JOIN w ON w.item_id = f.item_id GROUP BY f.item_id ORDER BY n DESC, item
